// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ACCURAL_DEPOSIT} from "../src/ACCURAL_DEPOSIT.sol";

contract InvMutTest is Test {
    ACCURAL_DEPOSIT c;
    function setUp() public { c = new ACCURAL_DEPOSIT(); }
    function testFuzz_property(uint256 newVal, address caller) public {
        vm.assume(newVal != 0);
        vm.prank(caller);
        c.SetMinSum(newVal);
        assertTrue(c.MinSum() == newVal, "SetMinSum must store the requested value before initialization");
    }
}
